import{_ as t,o as r,c as e,a2 as a}from"./chunks/framework.CcLa3K2D.js";const l=JSON.parse('{"title":"术语表（Glossary）","description":"","frontmatter":{},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md"}'),n={name:"glossary.md"};function s(g,o,h,p,i,d){return r(),e("div",null,[...o[0]||(o[0]=[a('<h1 id="术语表-glossary" tabindex="-1">术语表（Glossary） <a class="header-anchor" href="#术语表-glossary" aria-label="Permalink to &quot;术语表（Glossary）&quot;">​</a></h1><p>本电子书中出现的核心术语速查。</p><hr><h2 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A&quot;">​</a></h2><p><strong>Agent（智能体）</strong> 能对问题推理、自主决定采取什么行动、并迭代逼近答案的 AI 系统。与&quot;链&quot;沿固定路径执行不同，智能体会动态选择工具。遵循 ReAct 模式（推理 + 行动）。见 <a href="/lang-chain-js-cn/guide/agents">第 5 章</a>。</p><p><strong>Agent Loop（智能体循环）</strong> 智能体反复&quot;思考 → 行动 → 观察&quot;直到解决问题的迭代过程。</p><p><strong>AIMessage</strong> 代表模型回复的消息类型。多轮对话中通常会被加回历史。</p><hr><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><p><strong>Chain（链）</strong> 把若干步骤按固定顺序串起来的流程，前一步输出即后一步输入。用 LCEL（<code>|</code> 管道）构建。与智能体的区别是<strong>路径固定</strong>。</p><p><strong>Chunk / Chunking（切分）</strong> 把长文档拆成更小块的过程。小块检索更精准，大块上下文更足。见 <a href="/lang-chain-js-cn/guide/embeddings">第 7 章</a>。</p><p><strong>Chunk Overlap（块重叠）</strong> 相邻块之间共享的字符数，用来保住边界处的上下文。推荐取 chunkSize 的 10%~20%。</p><p><strong>Context Window（上下文窗口）</strong> 模型单次请求能处理的最大 token 数（含输入 + 输出）。超出就需要裁剪或总结历史。</p><p><strong>Cosine Similarity（余弦相似度）</strong> 衡量两个向量（嵌入）相似程度的指标，取值约 0~1，越接近 1 越相似。</p><hr><h2 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h2><p><strong>Document（文档）</strong> LangChain 处理文本的基本单位，由 <code>pageContent</code>（文本）与 <code>metadata</code>（元数据）组成。</p><p><strong>Document Loader（文档加载器）</strong> 把各种格式（txt / pdf / 网页 / csv……）读成 <code>Document</code> 的组件。</p><hr><h2 id="e" tabindex="-1">E <a class="header-anchor" href="#e" aria-label="Permalink to &quot;E&quot;">​</a></h2><p><strong>Embedding（嵌入）</strong> 把文本映射成数值向量，使语义相近的文本在向量空间中彼此靠近。&quot;比意思&quot;由此变成&quot;比数字&quot;。</p><p><strong>Embedding Model（嵌入模型）</strong> 把文本转成向量的模型，如 <code>text-embedding-3-small</code>、<code>BAAI/bge-m3</code>。</p><hr><h2 id="f" tabindex="-1">F <a class="header-anchor" href="#f" aria-label="Permalink to &quot;F&quot;">​</a></h2><p><strong>Few-Shot Prompting（少样本提示）</strong> 在提示词里给 2~5 个示例，让模型照着模仿，比只写规则更可靠。</p><p><strong>Function Calling（函数调用）</strong> 模型生成&quot;调用某函数 + 参数&quot;的结构化请求的能力。<strong>模型只描述，不执行</strong>；执行由你的代码完成。</p><hr><h2 id="h" tabindex="-1">H <a class="header-anchor" href="#h" aria-label="Permalink to &quot;H&quot;">​</a></h2><p><strong>HumanMessage</strong> 代表用户输入的消息类型。</p><hr><h2 id="l" tabindex="-1">L <a class="header-anchor" href="#l" aria-label="Permalink to &quot;L&quot;">​</a></h2><p><strong>LCEL（LangChain 表达式语言）</strong> 用 <code>|</code> 管道把组件串成链的语法，例如 <code>prompt | model | parser</code>。</p><p><strong>LLM（大语言模型）</strong> 在海量文本上训练、能理解与生成自然语言的模型。</p><hr><h2 id="m" tabindex="-1">M <a class="header-anchor" href="#m" aria-label="Permalink to &quot;M&quot;">​</a></h2><p><strong>maxTokens</strong> 限制回复长度的参数，用来控制成本与篇幅。</p><p><strong>MCP（Model Context Protocol，模型上下文协议）</strong> 让 AI 应用通过统一接口连接外部工具与数据源的开放标准，常被比作&quot;AI 世界的 USB-C&quot;。见 <a href="/lang-chain-js-cn/guide/mcp">第 6 章</a>。</p><p><strong>MCP Server</strong> 按 MCP 协议暴露工具/能力的程序（如文件系统、数据库、文档服务）。</p><p><strong>Memory（记忆）</strong> 让应用&quot;记住&quot;之前交互的能力。实现方式就是每次把对话历史一起发过去——模型本身是无状态的。</p><p><strong>Metadata（元数据）</strong> 附加在文档上的信息（来源、分类、日期……），用于过滤、分类、溯源。切分时会自动复制到每个子块。</p><p><strong>Middleware（中间件）</strong> 在模型调用/工具调用前后插入逻辑的机制，用于日志、成本优化、错误兜底、注入上下文等。</p><p><strong>MMR（最大边际相关）</strong> 一种检索策略，在&quot;相关性&quot;与&quot;多样性&quot;之间平衡，避免返回一堆近乎重复的结果。</p><hr><h2 id="o" tabindex="-1">O <a class="header-anchor" href="#o" aria-label="Permalink to &quot;O&quot;">​</a></h2><p><strong>Output Parser（输出解析器）</strong> 把模型原始输出转成结构化数据的组件。LangChain v1 更推荐直接用 <code>withStructuredOutput</code>。</p><hr><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P&quot;">​</a></h2><p><strong>Prompt（提示词）</strong> 你给模型的指令、问题或上下文。</p><p><strong>Prompt Template（提示词模板）</strong> 带占位符（变量）的可复用提示词结构。使提示词可测试、可维护，并降低提示词注入风险。</p><p><strong>Provider（服务商）</strong> 提供 LLM 接口的公司（OpenAI、Anthropic、DeepSeek、Azure、硅基流动……）。LangChain 用统一接口适配它们。</p><hr><h2 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h2><p><strong>RAG（检索增强生成）</strong> 先检索相关文档，再把它们作为上下文交给模型生成答案，让模型用上外部知识。</p><p><strong>Rate Limit（限流）</strong> 服务商对单位时间内请求数/ token 数的限制，超限返回 429。用 <code>withRetry()</code> 自动退避重试。</p><p><strong>ReAct</strong> &quot;Reasoning + Acting&quot;的推理模式：思考 → 行动 → 观察 → 重复 → 回答。</p><p><strong>Retriever（检索器）</strong> 在向量库中按查询返回最相关文档的组件，屏蔽底层检索策略差异。</p><hr><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><p><strong>Semantic Search（语义搜索）</strong> 按&quot;意思&quot;而非&quot;字面关键词&quot;检索。用嵌入实现。</p><p><strong>Streaming（流式输出）</strong> 逐块返回生成内容而非等全部生成完，显著改善&quot;感知速度&quot;。</p><p><strong>SystemMessage</strong> 设定模型身份、语气与行为准则的消息类型。</p><hr><h2 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h2><p><strong>Temperature（温度）</strong> 控制随机性的参数。0 最确定，越高越发散有创意。注意不同模型支持范围不同。</p><p><strong>Token（词元）</strong> 模型处理文本的最小单位。粗略换算：1 token ≈ 4 字符 ≈ ¾ 个英文单词。既影响成本也影响速度。</p><p><strong>Tool（工具）</strong> 模型可调用的函数，用于执行计算、查库、调 API 等，扩展模型能力边界。</p><p><strong>ToolMessage</strong> 承载工具执行结果的消息类型，回传给模型让它组织最终答案。</p><p><strong>Text Splitter（文本切分器）</strong> 把长文档拆成小块的组件。推荐 <code>RecursiveCharacterTextSplitter</code>。</p><hr><h2 id="v" tabindex="-1">V <a class="header-anchor" href="#v" aria-label="Permalink to &quot;V&quot;">​</a></h2><p><strong>Vector（向量）</strong> 一串数字（如 1536 维），表示文本的语义。使文本相似度可以用数学计算。</p><p><strong>Vector Store（向量库）</strong> 专门存储与检索向量的数据库，支持快速相似度搜索。如 <code>MemoryVectorStore</code>、Chroma、Pinecone、Qdrant。</p><hr><h2 id="z" tabindex="-1">Z <a class="header-anchor" href="#z" aria-label="Permalink to &quot;Z&quot;">​</a></h2><p><strong>Zod</strong> TypeScript 优先的 schema 校验库。在 LangChain.js 中用于定义工具参数和结构化输出的形状，同时提供编译期类型与运行期校验。</p><p><strong>withStructuredOutput</strong> 让模型直接返回符合 Zod schema 的对象的方法，避免手工解析 JSON。不同服务商支持的模式不同（<code>jsonSchema</code> / <code>functionCalling</code> / <code>jsonMode</code>），兼容性最好的是 <code>functionCalling</code>。</p>',76)])])}const u=t(n,[["render",s]]);export{l as __pageData,u as default};
